    assert_eq!(new_files.len(), 1);
    for file in new_files {
        let current = std::fs::read_to_string(root.join(file["path"].as_str().unwrap())).unwrap();
        assert_eq!(digest(&current), file["sha256"]);
        assert_ne!(digest(&(current + "\n")), file["sha256"]);
    }
